const HEALTH_ROOT = `${API_URL}/api/sections/health`;

// Every interpolated path segment goes through `encodeURIComponent`; before
// this the file encoded 42 of 85 and left the rest raw, with nothing
// distinguishing the two groups. `offline-api-router.ts` decodes to match.
const api = createJsonClient(HEALTH_ROOT);

/**
 * Story 338 — a failed label read, carrying WHY as a field rather than as
 * prose. The caller's next move differs by reason and text-matching a message
 * to decide it is how `ImageUploadError` came to exist too:
 *   - `unreadable`  the model saw the photo and got nothing usable. Another
 *                   shot of the same label will not help; hand the user a form.
 *   - `unavailable` GPU busy, llama-server down, offline, timed out. The photo is
 *                   fine — retrying is the fix.
 */
export class LabelReadError extends Error {
    constructor(message: string, public readonly reason: 'unreadable' | 'unavailable') {
        super(message);
        this.name = 'LabelReadError';
    }
}

