    // --- AI estimation ---

    /**
     * Story 338 — read a photographed nutrition table into a DRAFT food item.
     *
     * Bypasses the JSON client for three reasons: its own budget, the
     * `X-Manual-AbortSignal` opt-out that stops the service worker
     * capping a vision call at 15 s, and an abort message a person can act on.
     * Shorter budget than the estimate's: this is one chat over one image, run
     * while someone stands in a shop holding the package, not a multi-ingredient
     * pipeline they walked away from.
     *
     * Server-only by design — it needs the GPU, so there is no offline
     * counterpart and an offline call fails as a network error, which is the
     * honest answer.
     */
    static async readNutritionLabel(image_path: string): Promise<LabelReadResult> {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 90_000);

        try {
            const response = await fetch(`${HEALTH_ROOT}/food-items/read-label`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'X-Manual-AbortSignal': 'true' },
                body: JSON.stringify({ image_path }),
                signal: controller.signal,
            });
            if (!response.ok) {
                const data = await response.json().catch(() => ({})) as { error?: string; reason?: string };
                throw new LabelReadError(
                    data.error ?? `Label read failed: ${response.status}`,
                    data.reason === 'unreadable' ? 'unreadable' : 'unavailable',
                );
            }
            return response.json();
        } catch (err: any) {
            if (err.name === 'AbortError') {
                throw new LabelReadError(
                    'Reading the label timed out. The GPU may be busy — try again, or type the values in by hand.',
                    'unavailable',
                );
            }
            throw err;
        } finally {
            clearTimeout(timeoutId);
        }
    }

